<?php declare(strict_types=1);
use Kulturhus\Verein\{ContributionInvoices,ContributionReminders,ContributionMail,SettingsSchema,MailPolicy};
use Kulturhus\Verein\Finance\Contributions\ContributionRunInput;
use Kulturhus\Native\Shared\Db;
use Kulturhus\Native\Delivery\MailMessage;

/** Genuine draft-to-issued revisions, original bank values and actual captured MIME inputs. */
function ownContributionRunOriginals(PDO $db,callable $check,array $f,array $failures):array
{
    $actor=$f['actor'];$club=$f['club'];$settings=$f['settings'];$finance=$f['finance'];$tables=$f['tables'];($f['payer'])('own-issued-revision');$entry=$finance->createAnnualContribution('own-issued-revision',2026,'','2026-01-01');
    $clubSettings=$settings->section('club');$settings->save('club',array_replace($clubSettings['data'],['city'=>'']),$clubSettings['version']);$draft=(new ContributionInvoices($db,$actor))->issue($entry);$firstFile=Db::run($db,'SELECT * FROM document_files WHERE club_id=? AND document_id=? AND revision=1',[$club,$draft['document_id']])->fetch();$check($draft['state']==='draft'&&json_decode($firstFile['snapshot'],true,64,JSON_THROW_ON_ERROR)['draft']===true,'actual incomplete contribution starts with a genuine unissued original draft revision');
    $settings->save('club',$clubSettings['data'],$clubSettings['version']+1);$issued=(new ContributionInvoices($db,$actor))->issue($entry);$read=(new ContributionInvoices($db,$actor))->currentOriginal($entry);$check($issued['state']==='issued'&&$read['file']['revision']===2&&$read['snapshot']['draft']===false,'actual completed contribution original is genuinely issued revision two after its earlier incomplete draft');
    $input=['data'=>['day'=>ContributionRunInput::today()]];$before=ownOriginalDatabaseHash($db,$tables);$review=$f['requests']->prepare($input);$check($review['source']['invoices'][$entry]['file']['revision']===2&&$review['source']['invoices'][$entry]['file']['sha256']===$read['file']['sha256']&&Db::run($db,'SELECT * FROM document_files WHERE club_id=? AND document_id=? AND revision=1',[$club,$draft['document_id']])->fetch()===$firstFile&&ownOriginalDatabaseHash($db,$tables)===$before,'native contribution plan reads the actual issued second PDF and preserves every whole earlier original including the first draft');
    $bank=$settings->section('bank');$settings->save('bank',array_replace($bank['data'],['holder'=>'Own later current contribution bank','iban'=>'DE12500105170648489890']),$bank['version']);$settings->save('club',array_replace($clubSettings['data'],['name'=>'Own later current association name']),$clubSettings['version']+2);$changed=ownOriginalDatabaseHash($db,$tables);$current=$f['requests']->prepare($input);$mail=ContributionMail::build($db,$club,$entry,'reminder');$check($current['hash']===$review['hash']&&str_contains($mail['text'],'DE89370400440532013000')&&!str_contains($mail['text'],'DE12500105170648489890')&&ownOriginalDatabaseHash($db,$tables)===$changed,'later General issuer and bank details neither redirect an issued contribution nor replace its actual reminder planning source');

    $templates=SettingsSchema::templates('texts_contributions');foreach(['invoice','reminder']as$type){$templates[$type]['subject']='Own whole '.$type.' {{RECHNUNGSNUMMER}} 0';$templates[$type]['message']='**Own '.$type.' formatting 0** __Own underline__ *Own emphasis* {{VEREINS_IBAN}} {{ZAHLBETRAG}}'."\n".str_repeat('🙂',1001);$templates[$type]['attach_pdf']=true;}$textSettings=$settings->section('texts_contributions');$settings->save('texts_contributions',$templates,$textSettings['version']);
    $worker=new ContributionReminders($db,$actor);$worker->run($input['data']['day'],true);$pending=Db::run($db,"SELECT * FROM contribution_deliveries WHERE club_id=? AND status='pending' ORDER BY id",[$club])->fetchAll();$expected=[];foreach($pending as$row){$original=(new ContributionInvoices($db,$actor))->currentOriginal($row['entry_id']);$expected[$row['recipient_email']]=['file'=>$original['file'],'snapshot'=>$original['snapshot'],'type'=>$row['type']];}
    $variables=['APP_URL','APP_ENV','VEREIN_MODE','KULTURHUS_DISABLE_MAIL','KULTURHUS_LOCAL_DEMO'];$originalEnv=[];foreach($variables as$variable){$originalEnv[$variable]=getenv($variable);putenv($variable);}
    try{
        $check(MailPolicy::allowed('https://owned-contribution.example.invalid')&&count($pending)===5,'actual source-backed contribution invoice and reminder orders reach the explicitly captured test transport');$calls=[];$sent=$worker->dispatch('https://owned-contribution.example.invalid',static function($to,$subject,$text,$html,$attachments)use(&$calls):bool{$calls[]=compact('to','subject','text','html','attachments');return true;},$input['data']['day']);$check($sent===5&&count($calls)===5,'actual contribution worker processes each genuine invoice and reminder once through capturing callbacks without SMTP');
        $invoiceCalls=0;$reminderCalls=0;
        foreach($calls as$call){$original=$expected[$call['to']];$type=$original['type'];if($type==='invoice')++$invoiceCalls;else++$reminderCalls;$file=$original['file'];$values=$original['snapshot']['values'];$mime=MailMessage::compose(['from'=>'preview@example.invalid','name'=>'Owned contribution MIME proof','reply_to'=>'preview@example.invalid'],['to'=>$call['to'],'subject'=>$call['subject'],'text'=>$call['text'],'html'=>$call['html'],'attachments'=>$call['attachments']]);$mimeBytes=$mime->toString();$check(str_contains($call['html'],'<strong>Own '.$type.' formatting 0</strong>')&&str_contains($call['html'],'<u>Own underline</u>')&&str_contains($call['html'],'<em>Own emphasis</em>')&&!str_contains($call['html'],'**Own '.$type.' formatting 0**')&&substr_count($call['text'],'🙂')===1001&&str_contains($call['html'],htmlspecialchars($values['VEREINSNAME'],ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'))&&str_contains($call['text'],'DE89370400440532013000')&&!str_contains($call['text'],'DE12500105170648489890')&&count($call['attachments'])===1&&hash_equals($file['sha256'],hash('sha256',$call['attachments'][0]['bytes']))&&str_contains($mimeBytes,'multipart/mixed'),'actual contribution '.$type.' MIME keeps whole Unicode rendered formatting original issuer bank reference and exact issued PDF');}
        $check($invoiceCalls===2&&$reminderCalls===3,'actual formatted contribution proof covers both distinct live template consumers');
    }finally{foreach($originalEnv as$variable=>$value)putenv($value===false?$variable:$variable.'='.$value);}
    $after=ownOriginalDatabaseHash($db,$tables);$check($f['requests']->receipt($f['first']['key'])===$f['first']&&(new \Kulturhus\Verein\Finance\Contributions\ContributionRunRequests($db,'own-contribution-other'))->receipt($failures['lossFirst']['key'])===$failures['lossFirst']&&ownOriginalDatabaseHash($db,$tables)===$after,'actual later captured delivery statuses retain both whole earlier private scheduling firsts without backfilling another approval');
    return compact('entry','draft','issued','firstFile','read');
}
